def classify(xs):
    if len(xs) < 2:
        return 'neither'
    if len({xs[i] - xs[i - 1] for i in range(1, len(xs))}) == 1:
        return 'arithmetic'
    if xs[0] != 0 and xs[1] % xs[0] == 0:
        r = xs[1] // xs[0]
        if r != 0 and all(xs[i] == xs[i - 1] * r for i in range(1, len(xs))):
            return 'geometric'
    return 'neither'

